import { chromium } from "playwright";
await new Promise(z=>setTimeout(z,70000));
const b=await chromium.launch();const ctx=await b.newContext({viewport:{width:390,height:844},deviceScaleFactor:2,hasTouch:true,isMobile:true,locale:"es-ES"});const pg=await ctx.newPage();const errs=[];pg.on("pageerror",e=>errs.push(e.message));
await pg.goto("https://kosmarafi.github.io/?t="+Date.now(),{waitUntil:"networkidle"});await pg.waitForTimeout(12000);
console.log("HTOP",(await pg.$eval("#hTop",e=>e.innerText)).replace(/\n+/g," | ").slice(0,500));
const before=await pg.evaluate(()=>RF_AT);
await pg.evaluate(()=>{window.scrollTo(0,0);const t=(type,y)=>{const touch=new Touch({identifier:1,target:document.body,clientX:200,clientY:y});document.dispatchEvent(new TouchEvent(type,{touches:type==="touchend"?[]:[touch],changedTouches:[touch],bubbles:true}))};t("touchstart",100);for(let y=110;y<=330;y+=20)t("touchmove",y);t("touchend",330)});
await pg.waitForTimeout(800);console.log("PTR",await pg.evaluate(()=>{const e=document.getElementById("ptr");return e&&e.className}),"refreshed",(await pg.evaluate(()=>RF_AT))>before);
const s=(await pg.screenshot({type:"jpeg",quality:50})).toString("base64");for(let i=0;i<s.length;i+=3000)console.log("PS"+String(i/3000).padStart(3,"0")+" "+s.slice(i,i+3000));
console.log("ERRS",JSON.stringify(errs).slice(0,400));await b.close();
